#!/usr/bin/env python3

import os
import json
import requests

def load_env_file(filepath):
    env_vars = {}
    with open(filepath, 'r') as f:
        for line in f:
            line = line.strip()
            if line and not line.startswith('#'):
                key, value = line.split('=', 1)
                env_vars[key.strip()] = value.strip()
    return env_vars

def main():
    env_vars = load_env_file('.env.test')
    response = requests.post('http://localhost:47301/api/design-review', json=env_vars)
    if response.status_code == 200:
        print("Review session registered successfully")
    else:
        print(f"Failed to register: {response.status_code}, {response.text}")

if __name__ == '__main__':
    main()
